/* Embedded artwork: eliminates missing asset URL on GitHub Pages. */
const EMBEDDED_MAP_IMAGE="data:image/webp;base64,";
'use strict';
const TOTAL=2863, SCALE=3, KEY='srodziemie.v1';
// Distances between verified chapter anchors are provisional allocations; detail atlas awaits source-by-source verification.
const stops=[
 {km:0,name:'Hobbiton',desc:'Początek wyprawy. Zielone wzgórza Shire zostają za plecami.',kind:'major',x:84,y:755},
 {km:105,name:'Stary Las',desc:'Z dala od spokojnych ścieżek Shire drzewa skrywają stare tajemnice.',x:130,y:693},
 {km:215,name:'Bree',desc:'W gospodzie Pod Rozbrykanym Kucykiem drogi wędrowców przecinają się.',kind:'major',x:180,y:618},
 {km:345,name:'Komarowe Bagna',desc:'Podmokłe odludzia rozciągają się na wschód od Bree.',x:209,y:549},
 {km:450,name:'Wichrowy Czub',desc:'Na ruinach dawnej strażnicy cienie stają się coraz bliższe.',kind:'major',x:262,y:480},
 {km:615,name:'Bród Bruinen',desc:'Przeprawa przez rzekę jest ostatnią przeszkodą przed bezpieczną doliną.',x:320,y:400},
 {km:737,name:'Rivendell',desc:'Imladris, dom Elronda. Miejsce wytchnienia i początek nowej części drogi.',kind:'major',x:355,y:345},
 {km:940,name:'Hollin',desc:'Ruiny dawnych elfickich krain u stóp Gór Mglistych.',x:310,y:303},
 {km:1090,name:'Caradhras',desc:'Niebezpieczna próba przekroczenia górskiej przełęczy.',x:265,y:260},
 {km:1230,name:'Moria',desc:'Wyprawa wiedzie przez ciemność Khazad-dûm.',kind:'major',x:291,y:207},
 {km:1481,name:'Lothlórien',desc:'Złote liście mallornów i ziemia Galadrieli.',kind:'major',x:340,y:165},
 {km:1710,name:'Anduina',desc:'Drużyna płynie Wielką Rzeką na południe.',x:410,y:230},
 {km:1940,name:'Argonath',desc:'Wielkie posągi dawnych królów strzegą rzeki.',x:456,y:316},
 {km:2107,name:'Rauros',desc:'U wodospadów kończy się wspólna droga Drużyny.',kind:'major',x:425,y:388},
 {km:2280,name:'Emyn Muil',desc:'Skaliste pustkowia wymagają wytrwałości.',x:493,y:444},
 {km:2410,name:'Martwe Bagna',desc:'W mrocznej wodzie odbijają się ślady dawnych bitew.',x:539,y:510},
 {km:2540,name:'Ithilien',desc:'Zielone ostępy na skraju kraju Cienia.',x:510,y:570},
 {km:2680,name:'Cirith Ungol',desc:'Niebezpieczna przełęcz nad doliną Morgul.',x:560,y:633},
 {km:2790,name:'Gorgoroth',desc:'Ostatnie mile przez jałową ziemię.',x:584,y:712},
 {km:2863,name:'Góra Przeznaczenia',desc:'U kresu drogi czeka Orodruina.',kind:'major',x:534,y:768}
];
const getDefault=()=>({schema:1,workouts:[],created:new Date().toISOString()});
function load(){try{const j=JSON.parse(localStorage.getItem(KEY));return j&&Array.isArray(j.workouts)?j:getDefault()}catch{return getDefault()}}
let data=load(),view='map',focused=null,mapZoom=1,mapPan={x:0,y:0};
const $=s=>document.querySelector(s), fmt=n=>Number(n||0).toLocaleString('pl-PL',{maximumFractionDigits:1}), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const real=()=>data.workouts.reduce((s,w)=>s+Number(w.km||0),0); const travel=()=>Math.min(TOTAL,real()*SCALE);const next=()=>stops.find(s=>s.km>travel());const discovered=()=>stops.filter(s=>s.km<=travel());
function save(){localStorage.setItem(KEY,JSON.stringify(data));render()}
function setView(v){view=v;focused=null;render()}
function toast(message){document.querySelector('.toast')?.remove();let n=document.createElement('div');n.className='toast';n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),3200)}
function closeSheet(){$('#overlay').hidden=true;$('#sheet').innerHTML=''}
function sheet(html){$('#sheet').innerHTML='<button class="close" aria-label="Zamknij" id="closeSheet">×</button>'+html;$('#overlay').hidden=false;$('#closeSheet').onclick=closeSheet}
function goToStop(i){const s=stops[i];const locked=s.km>travel();sheet(`<div class="illustration"></div><small class="eyebrow">${locked?'NIEODKRYTA LOKACJA':'KARTA ODKRYCIA'}</small><h2>${locked?'Nieznane miejsce':esc(s.name)}</h2>${locked?`<p>Dotrzesz tutaj po kolejnych <b>${fmt((s.km-travel())/SCALE)} km</b> rzeczywistego ruchu.</p><p class="note">Treść karty zostanie odsłonięta po osiągnięciu celu.</p>`:`<p>${esc(s.desc)}</p><p class="note">Odkrycie przy ${fmt(s.km)} km drogi fabularnej. Kilometraż pośredni jest roboczy.</p><div class="badge-card"><div class="symbol">✧</div><b>${s.kind==='major'?'Kamień milowy':'Odkryta lokacja'}</b><p class="tiny muted">Wpis zapisany w kronice podróży.</p></div>`}`)}
function routeCurve(pts){
 const f=n=>Number(n).toFixed(1);
 if(pts.length<2)return '';
 let d=`M${f(pts[0].x)} ${f(pts[0].y)}`;
 for(let i=0;i<pts.length-1;i++){
  const a=pts[Math.max(0,i-1)],b=pts[i],c=pts[i+1],e=pts[Math.min(pts.length-1,i+2)];
  const c1={x:b.x+(c.x-a.x)/6,y:b.y+(c.y-a.y)/6};
  const c2={x:c.x-(e.x-b.x)/6,y:c.y-(e.y-b.y)/6};
  d+=` C${f(c1.x)} ${f(c1.y)} ${f(c2.x)} ${f(c2.y)} ${f(c.x)} ${f(c.y)}`;
 }
 return d;
}
function mapSvg(){
 const k=travel(),chapter=k<737?0:k<1481?1:k<2107?2:3;
 const ranges=[[0,6],[6,10],[10,13],[13,19]];
 const [first,last]=ranges[chapter],chapterStops=stops.slice(first,last+1);
 // Artwork and data are independent: all pins and names remain vector sharp. Chapter I uses art-directed coordinates; later chapters retain provisional layouts.
 const xy=(t)=>chapter===0?{x:122+(t.x-84)*1.35,y:733-(755-t.y)*1.36}: {x:105+(t.x-stops[first].x)*1.45,y:725-(stops[first].y-t.y)*1.3};
 const chapterOne=[[122,825],[180,750],[220,665],[278,582],[355,500],[445,385],[528,255]];
 const pts=chapter===0?chapterOne.map(([x,y])=>({x,y})):chapterStops.map(xy); const path=routeCurve(pts);
 const from=stops[first].km,to=stops[last].km,completed=Math.max(0,Math.min(1,(k-from)/(to-from)));
 const current=(()=>{if(chapter!==0)return xy(positionAt(k));let j=chapterStops.findIndex(q=>q.km>=k);if(j<=0)return pts[0];let a=chapterStops[j-1],b=chapterStops[j],t=(k-a.km)/(b.km-a.km);return {x:pts[j-1].x+(pts[j].x-pts[j-1].x)*t,y:pts[j-1].y+(pts[j].y-pts[j-1].y)*t}})();
 const anchors=chapterStops.map((stop,i)=>{const p=pts[i],seen=stop.km<=k,major=stop.kind==='major',r=major?9:5.6;
  const label=seen||major?esc(stop.name):'?';const side=p.x>400?-1:1;
  return `<g class="stop map-pin ${seen?'unlocked':'locked'}" data-stop="${first+i}" tabindex="0" role="button" aria-label="${seen?esc(stop.name):'Nieodkryte miejsce'}"><circle cx="${p.x}" cy="${p.y}" r="${r+6}" fill="#050d0b" opacity=".85"/><circle cx="${p.x}" cy="${p.y}" r="${r}" fill="${seen?'#d2a75c':'#101b16'}" stroke="${seen?'#ffe7b1':'#c1ad82'}" stroke-width="${major?2.4:1.7}"/><text x="${p.x+side*18}" y="${p.y-15}" text-anchor="${side>0?'start':'end'}" class="map-label ${seen?'discovered':''}">${label}</text></g>`}).join('');
 return `<svg viewBox="0 0 640 1060" preserveAspectRatio="xMidYMid slice" role="group" aria-label="Mapa wyprawy ze ścieżką i interaktywnymi miejscami"><defs><linearGradient id="mapshade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#09100d" stop-opacity=".16"/><stop offset=".6" stop-color="#09100d" stop-opacity="0"/><stop offset="1" stop-color="#06100c" stop-opacity=".6"/></linearGradient><filter id="mapglow"><feGaussianBlur stdDeviation="7"/></filter></defs><rect width="640" height="1060" fill="url(#mapshade)"/><path d="${path}" fill="none" stroke="#101713" stroke-width="9" stroke-linejoin="round" stroke-linecap="round" opacity=".85"/><path d="${path}" fill="none" stroke="#ba9a66" stroke-width="2.7" stroke-dasharray="2 10" stroke-linecap="round" opacity=".8"/><path d="${path}" fill="none" stroke="#f3cd83" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" pathLength="1000" stroke-dasharray="${Math.max(0,completed*1000)} 1000" style="filter:drop-shadow(0 0 5px #d9ac5f)"/>${anchors}<circle cx="${current.x}" cy="${current.y}" r="28" fill="#ecc47d" opacity=".35" filter="url(#mapglow)"/><circle cx="${current.x}" cy="${current.y}" r="15" fill="none" stroke="#f2c37b" stroke-width="1.4"/><circle cx="${current.x}" cy="${current.y}" r="7" fill="#ffecbd" stroke="#ae7645" stroke-width="2"/><g transform="translate(555 850)" fill="none" stroke="#c8a36a" stroke-width="2" opacity=".9"><circle r="36"/><path d="M0 -49V49M-49 0H49M0 -30L9 0 0 30 -9 0Z"/><text y="-57" fill="#ddbf85" stroke="none" font-family="Georgia" font-size="15" text-anchor="middle">N</text></g></svg>`;
}
function positionAt(k){if(k<=0)return stops[0];for(let i=1;i<stops.length;i++){if(k<=stops[i].km){let a=stops[i-1],b=stops[i],t=(k-a.km)/(b.km-a.km);return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t}}}return stops.at(-1)}
function renderMap(){let chapter=travel()<737?1:travel()<1481?2:travel()<2107?3:4;let goal=[737,1481,2107,2863][chapter-1],start=[0,737,1481,2107][chapter-1];const n=next();return `<div class="map-stage" id="mapStage"><div class="map-art" id="mapArt"><img class="map-landscape" src="${EMBEDDED_MAP_IMAGE}" alt="" draggable="false" onerror="this.closest('.map-stage').classList.add('map-image-error')">${mapSvg()}</div><div class="map-legend"><strong>Rozdział ${['I','II','III','IV'][chapter-1]}</strong><p>${['Cienie nad Eriadorem','Przez Góry Mgliste','Wielka Rzeka','W cieniu Mordoru'][chapter-1]}</p></div><div class="map-tools"><button data-zoom="in" aria-label="Przybliż">+</button><button data-zoom="out" aria-label="Oddal">−</button><button data-zoom="reset" aria-label="Wyśrodkuj">⌖</button></div><div class="map-footer"><div class="statsline"><b>Do ${esc(stops.find(s=>s.km===goal)?.name||'celu')}</b><span class="subtle">${fmt(Math.max(0,travel()-start))} / ${fmt(goal-start)} km</span></div><div class="progress"><b style="width:${Math.min(100,100*(travel()-start)/(goal-start))}%"></b></div><div class="metrics"><div><strong>${fmt(real())}</strong><small>Realne kilometry</small></div><div><strong>${fmt(travel())}</strong><small>Droga w Śródziemiu</small></div><div><strong>${fmt(n?Math.max(0,(n.km-travel())/SCALE):0)}</strong><small>Do odkrycia (km)</small></div></div><button class="primary" style="margin-top:15px" id="newWorkout">+ Dodaj trening</button></div></div><div class="page"><p class="note">Ilustrowane tło jest autorską interpretacją krajobrazu, nie mapą geograficzną. Przebieg i dystanse punktów pośrednich pozostają robocze.</p></div>`}
function renderTraining(){let ws=[...data.workouts].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="page"><div class="panel"><div class="between"><div><small class="eyebrow">REJESTR AKTYWNOŚCI</small><h2 class="section-title" style="margin:8px 0">Twój dziennik</h2></div><span class="pill">${ws.length} treningów</span></div><button class="primary" id="newWorkout">+ Zapisz trening</button></div><div class="panel"><div class="metrics"><div><strong>${fmt(real())}</strong><small>Kilometry</small></div><div><strong>${fmt(ws.reduce((s,w)=>s+(+w.minutes||0),0)/60)}</strong><small>Godziny</small></div><div><strong>${fmt(ws.length?real()/ws.length:0)}</strong><small>Średni trening km</small></div></div></div><div class="panel"><h2 class="section-title">Historia aktywności</h2>${ws.length?ws.map(w=>`<div class="list-row"><div><strong>${esc(w.type)} · ${fmt(w.km)} km</strong><small>${esc(w.date)} · ${w.place==='treadmill'?'Bieżnia':'Teren'}${w.minutes?' · '+fmt(w.minutes)+' min':''}${w.runMinutes?' · bieg '+fmt(w.runMinutes)+' min':''}</small></div><button class="secondary" data-edit="${esc(w.id)}">Edytuj</button></div>`).join(''):'<div class="empty">Jeszcze nie ma treningów. Dodaj pierwszy albo wpisz wcześniejsze aktywności.</div>'}</div></div>`}
function weeklyStreak(){const keys=new Set(data.workouts.map(w=>weekKey(w.date)));if(!keys.size)return 0;let day=new Date();day.setHours(12,0,0,0);let n=0;for(let i=0;i<520;i++){const key=weekKey(day.toISOString().slice(0,10));if(keys.has(key))n++;else if(i!==0)break;day.setDate(day.getDate()-7)}return n}
function weekKey(s){const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+4-(d.getDay()||7));return d.getFullYear()+'-'+String(Math.ceil((((d-new Date(d.getFullYear(),0,1))/864e5)+1)/7)).padStart(2,'0')}
function renderChronicle(){const done=discovered(),future=stops.filter(s=>s.km>travel());return `<div class="page"><div class="panel"><small class="eyebrow">KRONIKA WYPRAWY</small><h2 class="section-title" style="margin:8px 0">Odkryte miejsca</h2><div class="statsline"><span class="muted">Odkrycia</span><b>${done.length} / ${stops.length}</b></div><div class="progress"><b style="width:${100*done.length/stops.length}%"></b></div></div>${[...done].reverse().map(s=>`<button class="discover" data-stop="${stops.indexOf(s)}" style="display:block;text-align:left;width:100%;color:inherit;margin:0 0 11px"><span class="eyebrow">${s.kind==='major'?'KAMIEŃ MILOWY':'ODKRYCIE'} · ${fmt(s.km)} KM</span><h3 class="mini-title" style="margin-top:9px">✧ ${esc(s.name)}</h3><span class="muted tiny">${esc(s.desc)}</span></button>`).join('')}<div class="panel"><h3 class="mini-title">Tajemnice na dalszej drodze</h3>${future.slice(0,8).map((s,i)=>`<div class="list-row"><div>🔒 ${s.kind==='major'?'Wielkie odkrycie':'Nieznany punkt'}</div><small>za ${fmt((s.km-travel())/SCALE)} km</small></div>`).join('')}</div><p class="note">Kronika odblokowuje kolejne miejsca na podstawie rzeczywistych treningów. Opisy są autorskimi streszczeniami, nie cytatami z książek.</p></div>`}
function barsChart(){const now=new Date(),samples=[];for(let i=7;i>=0;i--){let monday=new Date(now);monday.setDate(monday.getDate()-((monday.getDay()+6)%7)-i*7);const key=weekKey(monday.toISOString().slice(0,10));samples.push({key,km:data.workouts.filter(w=>weekKey(w.date)===key).reduce((s,w)=>s+(+w.km),0)})}let max=Math.max(5,...samples.map(s=>s.km));return `<svg class="chart" viewBox="0 0 330 155" role="img" aria-label="Dystans w ostatnich ośmiu tygodniach">${[0,1,2,3].map(i=>`<line class="gridline" x1="24" x2="318" y1="${125-i*35}" y2="${125-i*35}"/>`).join('')}${samples.map((s,i)=>`<rect class="bar" x="${35+i*36}" y="${125-98*s.km/max}" width="20" height="${98*s.km/max}" rx="3"/><text x="${45+i*36}" y="147" text-anchor="middle">${i+1}</text>`).join('')}</svg>`}
function renderGrowth(){let ws=data.workouts,minutes=ws.reduce((s,w)=>s+(+w.minutes||0),0),best=Math.max(0,...ws.filter(w=>w.type==='Bieg').map(w=>+w.km)),maxRun=Math.max(0,...ws.map(w=>+(w.longestRun||0))),withPace=ws.filter(w=>w.minutes>0&&w.km>0),totalPace=withPace.reduce((s,w)=>s+w.minutes,0)/Math.max(.01,withPace.reduce((s,w)=>s+w.km,0));return `<div class="page"><div class="panel"><small class="eyebrow">TWOJA KONDYCJA</small><h2 class="section-title" style="margin:8px 0 18px">Rozwój wytrzymałości</h2><div class="metrics"><div><strong>${fmt(real())}</strong><small>Przebyte km</small></div><div><strong>${fmt(minutes/60)}</strong><small>Godziny</small></div><div><strong>${weeklyStreak()}</strong><small>Seria tygodni</small></div></div></div><div class="panel"><h3 class="mini-title">Kilometry w ostatnich 8 tygodniach</h3>${barsChart()}<p class="note">Tydzień 1 = najstarszy. Wykres obejmuje marsz, bieg i interwały.</p></div><div class="two"><div class="panel"><div class="eyebrow">NAJDŁUŻSZY BIEG</div><h2 class="hero-title">${fmt(best)} km</h2><span class="note">Trening typu bieg</span></div><div class="panel"><div class="eyebrow">BIEG CIĄGŁY</div><h2 class="hero-title">${fmt(maxRun)} min</h2><span class="note">Jeśli zapisany</span></div></div><div class="panel"><h3 class="mini-title">Średnie tempo</h3><div class="hero-title">${withPace.length?fmt(totalPace)+' min/km':'—'}</div><p class="note">Średnia ważona dla wpisów zawierających czas. Zróżnicowane marsze i biegi analizuj osobno.</p></div><div class="panel"><h3 class="mini-title">Próby porównawcze</h3><p class="muted">Oznaczaj wybrane treningi jako próby, aby porównać wyniki przy podobnych warunkach.</p>${ws.filter(w=>w.test).length?ws.filter(w=>w.test).sort((a,b)=>a.date.localeCompare(b.date)).map(w=>`<div class="list-row"><div><b>${esc(w.date)}</b><small>${fmt(w.km)} km · ${fmt(w.minutes)} min · wysiłek ${w.rpe||'—'}/10</small></div></div>`).join(''):'<p class="note">Brak zapisanych prób. Możesz oznaczyć trening podczas jego dodawania lub edycji.</p>'}</div></div>`}
function render(){let labels={map:'Droga Pierścienia',training:'Dziennik treningów',chronicle:'Kronika podróży',growth:'Twoja kondycja'};$('#pageTitle').textContent=labels[view];$('#eyebrow').textContent=view==='map'?'WYPRAWA I • DROGA FRODA':'ŚRÓDZIEMIE • WYPRAWA I';$('#screen').innerHTML={map:renderMap,training:renderTraining,chronicle:renderChronicle,growth:renderGrowth}[view]();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#newWorkout')?.addEventListener('click',()=>workoutSheet());if(view==='map')attachMap()}
function attachMap(){const art=$('#mapArt'),stage=$('#mapStage');const apply=()=>{art.style.transform=`translate(${mapPan.x}px,${mapPan.y}px) scale(${mapZoom})`};apply();stage.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){mapZoom=1;mapPan={x:0,y:0}}else mapZoom=Math.max(1,Math.min(3.5,mapZoom+(b.dataset.zoom==='in'?.3:-.3)));apply()});let down=null;stage.onpointerdown=e=>{if(e.target.closest('button')||e.target.closest('.map-footer'))return;down={x:e.clientX,y:e.clientY,px:mapPan.x,py:mapPan.y};stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!down)return;mapPan={x:down.px+e.clientX-down.x,y:down.py+e.clientY-down.y};apply()};stage.onpointerup=()=>down=null}
function segmentsHtml(rows){return rows.map((r,i)=>`<div class="two segment" style="grid-template-columns:1.1fr .8fr .9fr auto"><select aria-label="Rodzaj odcinka" data-seg="kind"><option ${r.kind==='Marsz'?'selected':''}>Marsz</option><option ${r.kind==='Bieg'?'selected':''}>Bieg</option><option ${r.kind==='Rozgrzewka'?'selected':''}>Rozgrzewka</option><option ${r.kind==='Schłodzenie'?'selected':''}>Schłodzenie</option></select><input aria-label="Minuty odcinka" type="number" min="0.1" step="0.1" data-seg="minutes" value="${r.minutes||''}" placeholder="min"><input aria-label="Prędkość km/h" type="number" min="0" step="0.1" data-seg="speed" value="${r.speed||''}" placeholder="km/h"><button class="link-btn" type="button" data-remove-seg="${i}" aria-label="Usuń odcinek">×</button></div>`).join('')}
function workoutSheet(id=null){let old=data.workouts.find(w=>w.id===id)||{},detail=!!old.segments?.length,segments=(old.segments||[{kind:'Rozgrzewka',minutes:5,speed:5},{kind:'Bieg',minutes:2,speed:8},{kind:'Marsz',minutes:3,speed:5.5}]);function content(){sheet(`<h2>${id?'Edytuj trening':'Nowa aktywność'}</h2><form id="workoutForm"><div class="field"><label>Data</label><input required name="date" type="date" value="${esc(old.date||new Date().toLocaleDateString('sv-SE'))}" max="${new Date().toLocaleDateString('sv-SE')}"></div><div class="field"><label>Rodzaj aktywności</label><select name="type"><option ${old.type==='Marsz'?'selected':''}>Marsz</option><option ${old.type==='Bieg'?'selected':''}>Bieg</option><option ${old.type==='Interwały'?'selected':''}>Interwały</option></select></div><div class="segmented"><button type="button" data-place="treadmill" class="${old.place!=='outdoors'?'selected':''}">Bieżnia</button><button type="button" data-place="outdoors" class="${old.place==='outdoors'?'selected':''}">Teren</button></div><div class="two"><div class="field"><label>Dystans (km)</label><input name="km" required type="number" inputmode="decimal" min="0.01" step="0.01" value="${esc(old.km??'')}"></div><div class="field"><label>Czas (min, opcjonalnie)</label><input name="minutes" type="number" inputmode="decimal" min="0" step="0.1" value="${esc(old.minutes??'')}"></div></div><div class="segmented"><button type="button" data-detail="off" class="${!detail?'selected':''}">Szybki zapis</button><button type="button" data-detail="on" class="${detail?'selected':''}">Dokładne interwały</button></div><div id="details" ${detail?'':'hidden'}><div class="field"><label>Segmenty: rodzaj / czas min / km/h</label><div id="segments" style="display:grid;gap:7px">${segmentsHtml(segments)}</div><button type="button" class="secondary" id="addSegment">+ Dodaj odcinek</button></div><p class="note">Segmenty pomagają analizować trening. Podstawą drogi jest wpisany dystans z bieżni, bez automatycznego wyliczania.</p></div><div class="two"><div class="field"><label>Najdłuższy ciągły bieg (min)</label><input name="longestRun" type="number" min="0" step="0.1" value="${esc(old.longestRun??'')}"></div><div class="field"><label>Wysiłek (1–10)</label><input name="rpe" type="number" min="1" max="10" step="1" value="${esc(old.rpe??'')}"></div></div><div class="two"><div class="field"><label>Łączny czas biegu (min)</label><input name="runMinutes" type="number" min="0" step="0.1" value="${esc(old.runMinutes??'')}"></div><div class="field"><label>Nachylenie bieżni (%)</label><input name="incline" type="number" min="0" step="0.5" value="${esc(old.incline??'')}"></div></div><div class="field"><label>Notatka</label><textarea name="notes" rows="2">${esc(old.notes??'')}</textarea></div><label class="tiny"><input type="checkbox" name="test" ${old.test?'checked':''}> To próba porównawcza</label><div class="sheet-actions"><button type="submit" class="primary">Zapisz trening</button>${id?'<button type="button" class="secondary danger" id="deleteWorkout">Usuń</button>':''}</div></form>`);let place=old.place||'treadmill';$('#sheet').querySelectorAll('[data-place]').forEach(btn=>btn.onclick=()=>{place=btn.dataset.place;$('#sheet').querySelectorAll('[data-place]').forEach(x=>x.classList.toggle('selected',x===btn))});$('#sheet').querySelectorAll('[data-detail]').forEach(btn=>btn.onclick=()=>{detail=btn.dataset.detail==='on';$('#details').hidden=!detail;$('#sheet').querySelectorAll('[data-detail]').forEach(x=>x.classList.toggle('selected',x===btn))});function collectSegments(){return [...$('#segments').querySelectorAll('.segment')].map(el=>({kind:el.querySelector('[data-seg="kind"]').value,minutes:+el.querySelector('[data-seg="minutes"]').value,speed:+el.querySelector('[data-seg="speed"]').value})).filter(x=>x.minutes>0)}$('#addSegment').onclick=()=>{segments=collectSegments();segments.push({kind:'Marsz',minutes:3,speed:5});$('#segments').innerHTML=segmentsHtml(segments);bindRemove()};function bindRemove(){$('#segments').querySelectorAll('[data-remove-seg]').forEach(b=>b.onclick=()=>{segments=collectSegments();segments.splice(+b.dataset.removeSeg,1);$('#segments').innerHTML=segmentsHtml(segments);bindRemove()})}bindRemove();$('#workoutForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),w={id:id||crypto.randomUUID(),date:String(fd.get('date')),type:String(fd.get('type')),place,km:+fd.get('km'),minutes:fd.get('minutes')===''?null:+fd.get('minutes'),longestRun:fd.get('longestRun')===''?null:+fd.get('longestRun'),rpe:fd.get('rpe')===''?null:+fd.get('rpe'),runMinutes:fd.get('runMinutes')===''?null:+fd.get('runMinutes'),incline:fd.get('incline')===''?null:+fd.get('incline'),notes:String(fd.get('notes')),test:fd.has('test'),segments:detail?collectSegments():[]};if(!Number.isFinite(w.km)||w.km<=0||w.date>new Date().toLocaleDateString('sv-SE'))return toast('Sprawdź dystans i datę');if(id)data.workouts=data.workouts.map(t=>t.id===id?w:t);else data.workouts.push(w);save();closeSheet();toast(`Zapisano ${fmt(w.km)} km → ${fmt(w.km*SCALE)} km podróży`)};if(id)$('#deleteWorkout').onclick=()=>{if(confirm('Usunąć ten trening? Pozycja na mapie zostanie przeliczona.')){data.workouts=data.workouts.filter(w=>w.id!==id);save();closeSheet();toast('Trening usunięty')}}}content()}
function settings(){sheet(`<h2>Ustawienia i dane</h2><div class="panel"><p class="eyebrow">POSTĘP PODRÓŻY</p><div class="between"><b>Przelicznik</b><span>1 : 3</span></div><p class="note">${fmt(real())} km rzeczywistych → ${fmt(travel())} km na trasie. Ukończenie pierwszej wyprawy odblokuje kolejne w przyszłych wersjach.</p></div><div class="panel"><h3 class="mini-title">Kopia zapasowa</h3><p class="note">Dane znajdują się wyłącznie na tym urządzeniu. Regularnie pobieraj kopię JSON i zapisuj ją w Plikach lub iCloud Drive.</p><button class="primary" id="exportData">Pobierz kopię JSON</button><button class="secondary" id="importData" style="width:100%;margin-top:9px">Wczytaj kopię JSON</button></div><p class="note">Wersja 0.3 · Trasa wizualna i podział części odległości są robocze. Repozytorium nie zawiera Twoich treningów.</p>`);$('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify({...data,exported:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='srodziemie-kopia-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#importData').onclick=()=>$('#importFile').click()}
$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{let j=JSON.parse(await file.text());if(!Array.isArray(j.workouts)||j.workouts.some(w=>!(w.id&&/^\d{4}-\d\d-\d\d$/.test(w.date)&&Number.isFinite(+w.km)&&+w.km>0)))throw Error('Zły format danych');if(confirm(`Wczytać ${j.workouts.length} treningów? Obecne dane zostaną zastąpione.`)){data={schema:1,created:j.created||new Date().toISOString(),workouts:j.workouts};save();closeSheet();toast('Kopia została przywrócona')}}catch(err){toast('Nieprawidłowy plik kopii: '+err.message)}e.target.value=''});
$('#settingsBtn').onclick=settings;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#screen').addEventListener('click',e=>{const b=e.target.closest('[data-edit],[data-stop]');if(b?.dataset.edit)workoutSheet(b.dataset.edit);else if(b?.dataset.stop!==undefined)goToStop(+b.dataset.stop)});$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeSheet()});render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
